import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider the curve defined by (y - {c})^2 + 2{m}x(y - {c}) + {A}|x - {h}| = {B}. Its graph partitions the plane into several regions. Determine the exact area of the bounded region enclosed by this curve.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate parameters so the curve simplifies to two pairs of line segments, ensuring a bounded polygon.
# Choose k >= 3 to avoid trivial small shapes.
while True:
    k = rng.randint(3, 12)
    # m must divide 2*k^2 (so the final area 2*k^2/m is an integer), and m >= 2 for nontrivial slope.
    candidates = []
    for m in range(2, 12):
        if (2 * k * k) % m == 0:
            candidates.append(m)
    if not candidates:
        continue
    m = rng.choice(candidates)
    # Pick nonzero integer shifts to increase difficulty without altering area.
    h_choices = [i for i in range(-12, 13) if i != 0]
    c_choices = [i for i in range(-12, 13) if i != 0]
    h = rng.choice(h_choices)
    c = rng.choice(c_choices)
    # Make A and B so that B = (A/(2m))^2 = k^2 holds exactly.
    A = 2 * m * k
    B = k * k
    # Extra difficulty: avoid overly narrow shapes (ensure width t/m = k/m >= 1). If not, retry.
    if k < m:
        continue
    return {'m': m, 'A': A, 'h': h, 'c': c, 'B': B}

    def verifier(assign):
# Validate types and domain constraints
try:
    m = assign['m']
    A = assign['A']
    h = assign['h']
    c = assign['c']
    B = assign['B']
except KeyError:
    # Missing slot
    return (False, None)
# Basic type checks
if not all(isinstance(v, int) for v in [m, A, h, c, B]):
    # All parameters must be integers
    return (False, None)
# Difficulty/domain checks
if m < 2:
    # Trivial slope (m=1) disallowed to enforce difficulty
    return (False, None)
if A <= 0:
    return (False, None)
if h == 0 or c == 0:
    # Require nonzero shifts to avoid trivial symmetry
    return (False, None)
# Ensure perfect-square structure: B == (A/(2m))^2 exactly
# Check via cross-multiplication to avoid floating errors.
if B * 4 * m * m != A * A:
    # If this fails, the curve does not degenerate to line segments and the bounded region may not be polygonal.
    return (False, None)
# Compute k from A and m and cross-check with B
# Since A = 2*m*k in valid instances, k = A // (2*m)
if A % (2*m) != 0:
    return (False, None)
k = A // (2*m)
if k * k != B:
    return (False, None)
# Ensure non-degenerate width t/m = k/m >= 1 for difficulty
if k < m:
    return (False, None)
# Area of bounded region for (y - c)^2 + 2 m x (y - c) + A |x - h| = B with B = (A/(2m))^2
# Derived formula: area = 2 * (A/(2m))^2 / m = 2*k^2 / m.
if (2 * k * k) % m != 0:
    # We enforce integral answer for robustness.
    return (False, None)
answer = (2 * k * k) // m
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

